function normalizeType(t) {
  const s = String(t || '').toLowerCase().trim();
  if (s === 'behavioral') return 'behavioral';
  if (s === 'situational' || s === 'gap_probe') return 'situational';
  if (s === 'cultural') return 'cultural';
  return 'technical';
}

// 1. Safely check execution source
const isWebhook = $("Webhook - /create-session").isExecuted;
const body = isWebhook 
  ? ($("Webhook - /create-session").first().json.body || {}) 
  : ($("When Executed by Another Workflow").first().json || {});

// 2. Extract account_id, round_instance_id, and HR questions safely
const accountId = body.account_id || $('Supabase - Create interview_session').first().json.account_id;
const roundInstanceId = body.round_instance_id || body.id || $('Supabase - Create interview_session').first().json.round_instance_id;
const hrProvided = body.questions;

let questionList = [];
if (Array.isArray(hrProvided) && hrProvided.length > 0) {
  // HR-reviewed path
  questionList = hrProvided
    .filter(q => q && String(q.question_text || '').trim())
    .map(q => ({ text: String(q.question_text).trim(), type: normalizeType(q.question_type) }));
} else {
  // Fallback: WF6's own auto-generator output
  const raw = $json.message?.content ?? $json.choices?.[0]?.message?.content ?? '{"questions":[]}';
  let parsed; 
  try { 
    parsed = JSON.parse(raw); 
  } catch (e) { 
    parsed = { questions: [] }; 
  }
  questionList = (parsed.questions || []).map(q => ({ text: q.text, type: normalizeType(q.type) }));
}

const intro = {
  account_id: accountId,
  round_instance_id: roundInstanceId,
  question_number: 1,
  question_text: 'Hello! I am your AI Interviewer today. Welcome to your interview. To start off, how are you doing today?',
  question_type: 'cultural'
};

const rows = questionList.map((q, i) => ({
  account_id: accountId,
  round_instance_id: roundInstanceId,
  question_number: i + 2,
  question_text: q.text,
  question_type: q.type
}));

return [intro, ...rows].map(question => ({ json: question }));

