// ═══════════════════════════════════════════════════════════════
// BUILD UNIFIED PROMPT — Ultra-Low Latency Dual-Prompt (System/User)
// Slashes Input & Generation Tokens for Fastest Turnaround
// ═══════════════════════════════════════════════════════════════
const context = $node["Supabase - Resolve Session (per-turn)"].json || {};
const session = context.session || context;
const body = $node["Webhook - /interview-engine (per turn)"].json.body || {};

const questionRows = (context.questions || ($items("Supabase - Fetch Questions (per-turn)") || []).map(i => i.json)).filter(q => q && (q.question_number !== undefined || q.order_index !== undefined));
const answerRows = (context.answers || ($items("Supabase - Fetch Answers (per-turn)") || []).map(i => i.json)).filter(a => a && a.question_id !== undefined);

const blueprintRow = questionRows.find(q => q.question_type === 'blueprint_meta');
let blueprint = { competencies: [], candidate_summary: {}, constraints: {}, jd_text: '', resume_summary: '' };
if (blueprintRow) { try { blueprint = JSON.parse(blueprintRow.question_text); } catch (e) {} }

const realQuestions = questionRows.filter(q => q.question_type !== 'blueprint_meta').sort((a, b) => (a.question_number ?? a.order_index ?? 0) - (b.question_number ?? b.order_index ?? 0));
const questionMap = {}; realQuestions.forEach(q => { questionMap[q.id] = q; });

const currentQuestionId = body.question_id;
const currentQuestion = questionMap[currentQuestionId] || realQuestions[0] || {};
const answer = body.answer_text || '';

const history = answerRows.map(a => ({
  question: questionMap[a.question_id]?.question_text || 'Unknown',
  answer: a.answer_text || '(no answer)',
  type: questionMap[a.question_id]?.question_type || 'technical'
}));

// Retain only last 2 turns to minimize input token processing time
const recentHistory = history.slice(-2);
const historyText = recentHistory.length
  ? recentHistory.map((item, i) => `Q${i + 1}: ${item.question}\nA${i + 1}: ${item.answer}`).join('\n\n')
  : 'Opening turn.';

const truncate = (t, max) => !t ? '' : (t.length > max ? t.slice(0, max) + '...' : t);
const resumeText = truncate(blueprint.resume_summary || '', 600);
const jdText = truncate(blueprint.jd_text || '', 400);

const hasAnswer = !!(answer && answer.trim());
const questionType = currentQuestion.question_type || 'technical';
const isAlreadyFollowUp = !!body.is_already_follow_up;

// Next question determination
const answeredIds = new Set(answerRows.map(a => a.question_id));
const nextQuestion = realQuestions.find(q => !answeredIds.has(q.id) && q.id !== currentQuestionId);
const focusInstruction = nextQuestion
  ? `Next official question to ask: "${nextQuestion.question_text}"`
  : 'Final turn reached. Deliver a warm closing turn asking if candidate has anything to add.';

// Compact Lean System Prompt
const system_prompt = `You are Alex, an expert technical recruiter conducting a live interview.
Evaluate the candidate's response and formulate the immediate next interview turn.

Rules:
1. If the current question is already a follow-up, or the answer provides genuine evidence, or candidate says "I don't know" -> recommended_action MUST be "advance".
2. Only choose "follow_up" if the candidate gave a relevant technical claim that lacks one critical mechanism/detail.
3. interviewer_text: Exactly 1 natural acknowledgment sentence (max 12 words). No exclamation marks, no generic praise.
4. question_text: Exactly 1 question. If advance, use the provided official next question verbatim or lightly adapted for flow.
5. Return ONLY valid JSON with this exact compact schema:
{
  "authenticity_signal": "genuine|vague|suspicious",
  "depth_signal": "deep|surface|empty",
  "recommended_action": "advance|follow_up",
  "interviewer_text": "...",
  "question_text": "..."
}`;

// Dynamic User Prompt (Turn specific)
let user_prompt;
if (hasAnswer) {
  user_prompt = `Current Question: "${currentQuestion.question_text || ''}"\nIs Follow-up: ${isAlreadyFollowUp ? 'yes' : 'no'}\nCandidate Answer: "${answer}"\n\n${focusInstruction}\n\nCandidate Profile: ${resumeText || 'None'}\nRole Context: ${jdText || 'Standard technical role'}\nRecent History:\n${historyText}`;
} else {
  user_prompt = `Opening turn of the interview.\n${focusInstruction}\nCandidate Profile: ${resumeText || 'None'}\nRole Context: ${jdText || 'Standard technical role'}`;
}

return [{
  json: {
    system_prompt,
    user_prompt,
    hasAnswer,
    questionType,
    currentQuestionId,
    nextQuestionId: nextQuestion ? nextQuestion.id : null,
    nextQuestionText: nextQuestion ? nextQuestion.question_text : null,
    isFinal: !nextQuestion
  }
}];

const build = $node["Code - Build Unified Prompt"].json;

// Support Claude (content[0].text) and OpenAI (choices[0].message.content) formats
let rawText = null;
if (Array.isArray($json.content) && $json.content[0]?.text) {
  rawText = $json.content[0].text;
} else if ($json.choices?.[0]?.message?.content) {
  rawText = $json.choices[0].message.content;
} else if ($json.message?.content) {
  rawText = $json.message.content;
}

// Clean markdown fences if any (e.g. ```json ... ```)
let content = {};
if (rawText) {
  let cleaned = rawText.trim();
  if (cleaned.startsWith('```json')) cleaned = cleaned.replace(/^```json\s*/i, '').replace(/\s*```$/, '');
  else if (cleaned.startsWith('```')) cleaned = cleaned.replace(/^```\s*/i, '').replace(/\s*```$/, '');
  try { content = JSON.parse(cleaned); } catch(e) { content = {}; }
}

// Resilient Fallback if Claude times out or returns non-JSON: advance smoothly
if (!content.question_text) {
  content.authenticity_signal = 'genuine';
  content.depth_signal = 'standard';
  content.recommended_action = 'advance';
  content.interviewer_text = 'Understood, let us proceed to the next area.';
  content.question_text = build.nextQuestionText || 'Could you walk me through your recent project experience?';
}

if (build.hasAnswer) {
  content.turn_type = content.recommended_action === 'advance' ? 'question' : 'follow_up';
} else {
  content.authenticity_signal = null;
  content.depth_signal = null;
  content.recommended_action = 'advance';
  content.turn_type = 'question';
}

// Downstream database & frontend contract fields
content.competency_evidence = content.competency_evidence || [];
content.note = content.note || `${content.authenticity_signal || 'Evaluated'} - ${content.depth_signal || 'standard'}`;
content.confidence = content.confidence ?? 1.0;
content.follow_up_prompted = content.recommended_action === 'follow_up';
content.answer_was_irrelevant = content.answer_was_irrelevant || false;
content.insufficiency_reason = content.insufficiency_reason || null;
content.follow_up_direction = content.follow_up_direction || null;
content.rephrase_direction = content.rephrase_direction || null;
content.requested_clarification = content.requested_clarification || false;

content.question_type = build.questionType;
content.next_question_id = build.nextQuestionId;
content.is_final_question = build.isFinal;

return [{ json: content }];

