// Normalize the interview_answers count regardless of how the Supabase REST response arrived
// (a single item wrapping the whole JSON array, or auto-split into one item per row) - this node
// always runs once (Code node default mode), so it reports 0 correctly even with zero input items.
const items = $input.all();
let count;
if (items.length === 1 && Array.isArray(items[0].json)) {
  count = items[0].json.length;
} else if (items.length === 1 && items[0].json && typeof items[0].json === 'object' && Object.keys(items[0].json).length === 0) {
  count = 0;
} else {
  count = items.length;
}
return [{ json: { answer_count: count } }];

// ─────────────────────────────────────────────────────────────
// COMPILE DATA — merges questions/answers/proctoring into the
// anti-inflation scoring prompt (doc2), keyed on WF6's
// account_id/round_instance_id instead of doc2's session_id.
// ─────────────────────────────────────────────────────────────
const session = $node["Supabase - Resolve Session (score)"].json;

const questionRows = ($items("Supabase - Get All Questions (score)") || []).map(i => i.json).filter(q => q && q.question_number !== undefined);
const answerRows = ($items("Supabase - Get All Answers") || []).map(i => i.json).filter(a => a && a.question_id !== undefined);
const proctoringRows = ($items("Supabase - Get All Proctoring Events (score)") || []).map(i => i.json).filter(e => e && e.event_type !== undefined);

const blueprintRow = questionRows.find(q => q.question_type === 'blueprint_meta');
let blueprint = { jd_text: '', resume_summary: '' };
if (blueprintRow) { try { blueprint = JSON.parse(blueprintRow.question_text); } catch (e) {} }

const questionMap = {}; questionRows.forEach(q => { questionMap[q.id] = q; });

const answerList = answerRows.map(a => {
  const liveNote = a.ai_live_note || {};
  const wordCount = (a.answer_text || '').trim().split(/\s+/).filter(Boolean).length;
  return {
    question: questionMap[a.question_id]?.question_text || 'Unknown',
    answer: a.answer_text || 'No answer provided',
    type: questionMap[a.question_id]?.question_type || 'technical',
    word_count: wordCount,
    depth_signal: liveNote.depth_signal || null,
    authenticity_signal: liveNote.authenticity_signal || null,
    insufficiency_reason: liveNote.insufficiency_reason || null,
    follow_up_triggered: liveNote.follow_up_prompted || false,
    requested_clarification: liveNote.requested_clarification || false,
    recruiter_note: liveNote.note || null,
  };
});

const technicalAnswers = answerList.filter(a => a.type === 'technical');
const depthCounts = { deep: 0, surface: 0, empty: 0, unknown: 0 };
const authCounts = { genuine: 0, vague: 0, suspicious: 0, inconsistent: 0, unknown: 0 };
let followUpTriggeredCount = 0, clarificationRequestCount = 0, insufficientTechnicalCount = 0;
answerList.forEach(a => {
  const d = a.depth_signal || 'unknown'; depthCounts[d] = (depthCounts[d] || 0) + 1;
  const auth = a.authenticity_signal || 'unknown'; authCounts[auth] = (authCounts[auth] || 0) + 1;
  if (a.follow_up_triggered) followUpTriggeredCount++;
  if (a.requested_clarification) clarificationRequestCount++;
  if (a.type === 'technical' && (a.depth_signal === 'empty' || a.insufficiency_reason)) insufficientTechnicalCount++;
});
const totalAnswered = answerList.length;
const emptyRatio = totalAnswered > 0 ? depthCounts.empty / totalAnswered : 0;
const techEmptyRatio = technicalAnswers.length > 0 ? insufficientTechnicalCount / technicalAnswers.length : 0;

const signalSummary = {
  total_answers: totalAnswered, depth_distribution: depthCounts, authenticity_distribution: authCounts,
  follow_up_triggered_count: followUpTriggeredCount, clarification_request_count: clarificationRequestCount,
  insufficient_technical_count: insufficientTechnicalCount,
  empty_answer_ratio: Math.round(emptyRatio * 100) + '%', tech_insufficient_ratio: Math.round(techEmptyRatio * 100) + '%',
};

const criticalEvents = proctoringRows.filter(e => e.severity === 'critical');
const warningEvents = proctoringRows.filter(e => e.severity === 'warning');
const countByType = {}; proctoringRows.forEach(e => { countByType[e.event_type] = (countByType[e.event_type] || 0) + 1; });
let proctoringRisk = 'low';
if (criticalEvents.length >= 5 || proctoringRows.length >= 20) proctoringRisk = 'high';
else if (criticalEvents.length >= 2 || warningEvents.length >= 5) proctoringRisk = 'medium';
const notableEvents = [...criticalEvents, ...warningEvents].slice(0, 10).map(e => ({ type: e.event_type, severity: e.severity, timestamp: e.timestamp }));
const proctoringSummary = { total_events: proctoringRows.length, critical_count: criticalEvents.length, warning_count: warningEvents.length, risk_level: proctoringRisk, by_type: countByType, notable_events: notableEvents };

const truncate = (t, max) => !t ? '' : (t.length > max ? t.slice(0, max) + '...[truncated]' : t);
const jdText = blueprint.jd_text || '';
const resumeText = blueprint.resume_summary || '';

const prompt = `You are a senior technical recruiter writing a post-interview evaluation. Score ACCURATELY and STRICTLY based only on what the candidate actually demonstrated live, not what their resume claims.

CRITICAL: ANTI-INFLATION RULES
1. Evidence required for every score above 65 - cite a specific answer, tool name, decision, outcome, or trade-off, or the score must be <= 65.
2. Vague answers do not earn high scores ("I've worked with React" alone -> max 45 technical for that question).
3. Live assessment signals are ground truth: depth_signal "empty" -> 0-20 for that question, "surface" -> 25-55, "deep" -> 65-100. authenticity_signal "suspicious"/"inconsistent" -> reduce authenticity_score heavily.
4. requested_clarification = true counts as a non-answer. 2+ such requests -> penalise communication and technical scores.
5. follow_up_triggered = true means the live analysis judged the initial answer too thin - factor this in even if a follow-up answer improved things.
6. Do not give benefit of the doubt. 50-60 is an honest score, not a bad one; reserve 80+ for clear, specific mastery.

LIVE SIGNAL CALIBRATION SUMMARY
${JSON.stringify(signalSummary, null, 2)}
Interpretation: empty_answer_ratio > 30% -> overall_score <= 45, recommendation no_go. tech_insufficient_ratio > 40% -> technical_score <= 30. follow_up_triggered_count >= 4 -> reduce technical/problem_solving by 15-20. clarification_request_count >= 2 -> reduce communication_score by 15-20. authenticity suspicious/inconsistent > 0 -> reduce authenticity_score 15-25 per occurrence.

SCORING DIMENSIONS (0-100): technical_score, communication_score, problem_solving_score, cultural_fit_score, authenticity_score (consistency between resume claims and live answers; proctoring risk factors in here too).
overall_score = (technical x 0.35) + (problem_solving x 0.20) + (communication x 0.15) + (cultural_fit x 0.15) + (authenticity x 0.15), rounded.

RECOMMENDATION THRESHOLDS: strong_hire (overall>=82, no critical red flags, authenticity>=70, technical>=75). hire (overall 68-81, no critical red flags, technical>=60). consider (overall 50-67, or 1-2 moderate red flags with solid technical foundation). no_go (overall<50 OR technical<40 OR critical red flags OR authenticity<35).

HARD SCORE CAPS (non-negotiable, apply before finalising): empty_answer_ratio>30% -> overall<=45 & no_go. tech_insufficient_ratio>40% -> technical<=30. 3+ empty technical depth_signals -> technical<=40. 2+ suspicious/inconsistent authenticity signals -> authenticity<=40. proctoring risk_level "high" -> authenticity<=40, name specific events. clarification_request_count>=3 -> communication<=45.

PROCTORING INTEGRITY: tab_switch/window_blur -> reduce authenticity_score 5-15 by frequency, flag if high volume. copy_paste/keyboard_shortcut -> reduce authenticity_score 15-25, always add to red_flags. face_absent/face_multiple -> flag only if 3+ events.

MANDATORY SELF-AUDIT before returning: (1) every score above 65 has cited evidence, else lower to 65; (2) technical_score matches depth_distribution; (3) scoring what was demonstrated, not what seemed likely; (4) hard caps checked explicitly; (5) recommendation matches thresholds.

Job Description:
"""
${truncate(jdText, 2500)}
"""

Resume:
"""
${truncate(resumeText, 2500)}
"""

Proctoring Summary:
${JSON.stringify(proctoringSummary, null, 2)}

Interview Q&A with Live Assessment Signals (${answerList.length} answers):
${JSON.stringify(answerList, null, 2)}

Return ONLY valid JSON:
{"technical_score":0,"communication_score":0,"problem_solving_score":0,"cultural_fit_score":0,"overall_score":0,"authenticity_score":0,"strengths":["specific, referencing an actual answer"],"weaknesses":["specific gap citing which question exposed it"],"red_flag_count":0,"red_flags":["specific flag with question context"],"recommendation":"strong_hire|hire|consider|no_go","ai_rationale":"2-3 sentence overview","detailed_rationale":"covers technical, communication, authenticity, proctoring, recommendation reasoning","resume_vs_reality":[{"claim":"...","status":"verified|suspicious|contradicted|unverifiable","evidence":"..."}]}`;

return [{
  json: {
    account_id: session.account_id,
    round_instance_id: session.round_instance_id,
    candidate_id: session.candidate_id,
    signalSummary, proctoringSummary,
    answers: answerList,
    prompt,
  }
}];

const content = JSON.parse($json.message?.content ?? $json.choices?.[0]?.message?.content ?? '{}');
const compileData = $node["Code - Compile Data (anti-inflation prompt)"].json;
const answers = compileData.answers || [];

const isRefusal = (ans) => {
  const clean = (ans || '').toLowerCase().trim();
  return (
    clean.length === 0 || clean === 'no answer recorded' ||
    clean.includes("i don't know") || clean.includes('dont know') || clean.includes('do not know') ||
    clean.includes('not sure') || clean.includes('no idea')
  );
};

const refusalCount = answers.filter(a => isRefusal(a.answer)).length;
const totalAnswers = Math.max(1, answers.length);
const refusalRate = refusalCount / totalAnswers;

let technical_score = Math.min(100, Math.max(1, Number(content.technical_score ?? 1)));
let communication_score = Math.min(100, Math.max(1, Number(content.communication_score ?? 1)));
let problem_solving_score = Math.min(100, Math.max(1, Number(content.problem_solving_score ?? 1)));
let cultural_fit_score = Math.min(100, Math.max(1, Number(content.cultural_fit_score ?? 1)));
let overall_score = Math.min(100, Math.max(1, Number(content.overall_score ?? 1)));
let authenticity_score = Math.min(100, Math.max(1, Number(content.authenticity_score ?? 1)));
let recommendation = content.recommendation || 'consider';

if (refusalRate >= 0.5) {
  technical_score = Math.min(technical_score, 15);
  problem_solving_score = Math.min(problem_solving_score, 15);
  overall_score = Math.min(overall_score, 15);
  recommendation = 'no_go';
} else if (refusalRate >= 0.3) {
  technical_score = Math.min(technical_score, 30);
  problem_solving_score = Math.min(problem_solving_score, 30);
  overall_score = Math.min(overall_score, 30);
  recommendation = 'no_go';
}

return [{
  json: {
    account_id: compileData.account_id,
    round_instance_id: compileData.round_instance_id,
    candidate_id: compileData.candidate_id,
    technical_score, communication_score, problem_solving_score, cultural_fit_score, overall_score, authenticity_score,
    red_flag_count: content.red_flag_count ?? 0,
    red_flags: content.red_flags || [],
    resume_vs_reality: content.resume_vs_reality || [],
    strengths: content.strengths || [],
    weaknesses: content.weaknesses || [],
    recommendation,
    ai_rationale: content.ai_rationale || '',
    detailed_rationale: content.detailed_rationale || '',
    signal_summary: compileData.signalSummary,
    proctoring_summary: compileData.proctoringSummary,
    scoring_model_version: 'gpt-4o-mini-v2-anti-inflation',
    evaluated_at: new Date().toISOString(),
  }
}];

// grant_platform_fault_retake returns a bare uuid (scalar), not a table row - PostgREST sends it
// back as a plain JSON string. n8n's HTTP Request node wraps a non-object JSON body under a `data`
// key when it parses the response, so read that first; fall back to the raw value defensively.
const raw = $input.first().json;
let retakeId;
if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
  retakeId = raw.data !== undefined ? raw.data : (raw.id !== undefined ? raw.id : Object.values(raw)[0]);
} else {
  retakeId = raw;
}
let faultReason;
try { faultReason = $('Set Fault Reason — Session Never Started').item.json.fault_reason; } catch (e) {}
if (!faultReason) {
  try { faultReason = $('Set Fault Reason — LLM Scoring Provider Error').item.json.fault_reason; } catch (e) {}
}
return [{ json: { retake_round_instance_id: retakeId, fault_reason: faultReason || 'unknown' } }];

